// NAV2 release candidate, blocker B3: a report is generated by ONE web request that the platform ends at 28 s. The application has its own hard
// deadline (22 s, from route entry), resumable preparation, an idempotency key, a typed 202 and typed timeout / failure states, and never leaves
// a partial or duplicate issued report.
//
// Evidence level: UNIT-TESTED (real service, real route, in-memory database that also emulates the two unique indexes). The unique index itself is
// PGLITE-VERIFIED in nav2ReleaseCandidate0281.test.ts. Timing at 1, 4, 10 and 20 funds is measured by scripts/nav2_rc/engine_timing.ts (local) and
// scripts/nav2_rc/dev_route_timing.mjs (the route against DEV).
//
// NAMED NEGATIVE CONTROLS
//   NC-T1  the same Idempotency-Key sent twice, sent six times at once, and sent after a timeout issue ONE report; a control without a key issues two
//          (so the key, not luck, is what prevents the duplicate); different keys issue different versions;
//   NC-T2  the same key with a DIFFERENT request (other period or other funds) is refused and issues nothing;
//   NC-T3  the clock is the whole request: time already spent before the service starts (sign-in, Premium, reads) shrinks what the engine may start;
//   NC-T4  a report whose engine ended too late to persist is NOT issued: the finished bundles are saved first, the answer is the typed "in steps"
//          state with every fund ready, and the next call only persists (it recomputes nothing);
//   NC-T5  preparation is resumable and monotonic: each call carries on where the last stopped, ready never goes down, and exactly ONE report is
//          issued at the end;
//   NC-T6  if the NAV range of any fund cannot be pinned, the report row just inserted is removed (nothing that looks final but is unprotected stays);
//   NC-T7  a database without migration 0281 still issues the report (without replay protection) instead of failing every request;
//   NC-T8  the route: a malformed key is a 422 before any work; a replay is 200 and a new report 201; an expired deadline is a typed 503 with
//          Retry-After; a failure is a typed retryable 500; two concurrent identical requests through the route issue one report.
import { describe, expect, it, vi } from 'vitest';
import type { SupabaseClient } from '@supabase/supabase-js';
import { CACHE_WRITE_RESERVE_MS, ENGINE_MS_PER_UNCACHED_FUND, GENERATION_BUDGET_MS, MIN_PERSIST_MS, PERSIST_AND_RESPONSE_RESERVE_MS, REQUEST_DEADLINE_MS } from '@/lib/config/nav2/reportLimits';
import { NAV2_POLICY } from '@/lib/config/nav2/metricPolicy';
import { reportAnalysisSpec } from '@/lib/engines/nav2/analysisSpec';
import type { FundAnalyticsInput, HeldSchemeInput } from '@/lib/engines/nav2/fundAnalyticsReport';
import { generateFundAnalyticsReport, IDEMPOTENCY_KEY_PATTERN, requestFingerprint, type FundAnalyticsDeps } from '@/lib/services/investment-intelligence/nav2/fundAnalyticsReportService';
import { raceDeadline } from '@/lib/services/investment-intelligence/nav2/requestDeadline';
import type { ReportNavGate } from '@/lib/services/investment-intelligence/pc6/reportNavHistoryGate';
import { createInMemoryDb, type InMemoryDb } from '../support/inMemorySupabase';
import { buildSeries, pathFromReturns, weekdays } from './support/fixtures';

const AS_OF = '2026-10-02';
const DATES = weekdays('2025-06-02', 260);
const USER = 'user-1';
const KEY = '0f8fad5b-d9cb-469f-a165-70867728950e';
const idOf = (i: number) => `00000000-0000-4000-8000-${String(i + 1).padStart(12, '0')}`;
const navsFor = (seed: number): number[] => pathFromReturns(100, Array.from({ length: DATES.length - 1 }, (_, i) => 0.0004 + 0.01 * Math.sin(i * 0.37 + seed) * Math.cos(i * 0.11 + seed * 2)));
function scheme(i: number): HeldSchemeInput {
  const id = idOf(i);
  const name = `Fund ${String(i + 1).padStart(2, '0')}`;
  return { instrumentId: id, schemeName: name, planType: 'direct', optionType: 'growth', category: 'flexi_cap', categoryLabel: 'Flexi Cap', series: buildSeries(DATES, navsFor(i + 1), { identity: { instrumentId: id, schemeName: name }, asOf: AS_OF }), benchmarks: [], investor: null, firstHeldDate: '2025-07-01' };
}
const inputFor = (n: number): FundAnalyticsInput => ({
  asOfDate: AS_OF, displayCurrency: 'INR', policy: NAV2_POLICY, spec: reportAnalysisSpec(AS_OF, NAV2_POLICY, 'since_first_held'), periodChoice: 'since_first_held', riskFree: null,
  schemes: Array.from({ length: n }, (_, i) => scheme(i)), scope: { entityHeldSchemesExcluded: 0, otherInstrumentsExcluded: 0, statementLinesAwaitingReview: 0, priceHistoryUnavailable: [] },
});
const openGate: ReportNavGate = { hold: false, funds: [], total: 1, loaded: 1, waiting: [], unavailable: [], heldSince: null, headline: null, disclosures: [] };

/** The in-memory database plus the two unique indexes the report table has: (user, version) and, from migration 0281, (user, idempotency key). */
function withUniqueIndexes(db: InMemoryDb, opts: { idempotencyColumns?: boolean; failDependencies?: boolean } = {}) {
  const idemColumns = opts.idempotencyColumns !== false;
  return {
    from: (table: string) => {
      if (table === 'nav2_report_nav_dependencies' && opts.failDependencies) {
        return { insert: () => ({ then: (res: (v: unknown) => unknown) => Promise.resolve(res({ data: null, error: { code: '23503', message: 'simulated: the dependency rows could not be written' } })) }) };
      }
      const real = db.client.from(table) as Record<string, (...a: unknown[]) => unknown>;
      if (table !== 'nav2_fund_analytics_reports') return real;
      return new Proxy(real, {
        get(target, prop) {
          if (prop !== 'insert') return (target as Record<string | symbol, unknown>)[prop];
          return (row: Record<string, unknown>) => {
            const existing = db.tables.nav2_fund_analytics_reports ?? [];
            const hasKeyCols = 'idempotency_key' in row;
            const fail = (code: string, message: string) => ({ select: () => ({ single: async () => ({ data: null, error: { code, message } }) }) });
            if (hasKeyCols && !idemColumns) return fail('PGRST204', "Could not find the 'idempotency_key' column of 'nav2_fund_analytics_reports' in the schema cache");
            if (existing.some((e) => e.user_id === row.user_id && e.version_number === row.version_number)) return fail('23505', 'duplicate key value violates unique constraint "nav2_fund_analytics_reports_user_version"');
            if (hasKeyCols && row.idempotency_key && existing.some((e) => e.user_id === row.user_id && e.idempotency_key === row.idempotency_key)) return fail('23505', 'duplicate key value violates unique constraint "uidx_nav2_reports_user_idempotency"');
            return target.insert(row);
          };
        },
      });
    },
  };
}

function setup(n: number, over: Partial<FundAnalyticsDeps> = {}, opts: { idempotencyColumns?: boolean; failDependencies?: boolean } = {}) {
  const db = createInMemoryDb();
  db.reset({ nav2_fund_analytics_reports: [], nav2_report_nav_dependencies: [], nav2_result_cache: [], ii_reference_job_control: [] });
  const admin = withUniqueIndexes(db, opts) as unknown as SupabaseClient;
  const load = vi.fn(async () => ({ input: inputFor(n), warnings: [], riskFreeUnavailableReason: null }));
  const deps: Partial<FundAnalyticsDeps> = { isFlagOn: async () => true, isPremium: async () => true, gate: async () => openGate, load, nowIso: () => '2026-10-02T06:00:00.000Z', nowMs: () => 0, ...over };
  const call = (o: { key?: string | null; period?: string; funds?: readonly string[] | null; requestStartedMs?: number } = {}) =>
    generateFundAnalyticsReport({ userId: USER, sessionClient: db.client as never, adminClient: admin, periodChoice: o.period ?? 'since_first_held', fundIds: o.funds ?? null, asOfDate: AS_OF, idempotencyKey: o.key === undefined ? null : o.key, requestStartedMs: o.requestStartedMs, deps });
  return { db, load, call, rows: () => db.tables.nav2_fund_analytics_reports };
}

describe('the limits are one consistent clock', () => {
  it('the deadline is well under the platform 28 s, the engine admission ends before the persist reserve, and the persist floor fits inside the reserve', () => {
    expect(REQUEST_DEADLINE_MS).toBeLessThanOrEqual(22_000);
    expect(REQUEST_DEADLINE_MS).toBeLessThan(28_000 - 5_000);
    expect(GENERATION_BUDGET_MS).toBe(REQUEST_DEADLINE_MS - PERSIST_AND_RESPONSE_RESERVE_MS);
    expect(MIN_PERSIST_MS).toBeLessThanOrEqual(PERSIST_AND_RESPONSE_RESERVE_MS);
    expect(ENGINE_MS_PER_UNCACHED_FUND).toBeGreaterThan(0);
  });
  it('the key pattern accepts a UUID and refuses short, long and unsafe keys', () => {
    expect(IDEMPOTENCY_KEY_PATTERN.test(KEY)).toBe(true);
    for (const bad of ['', 'short', 'x'.repeat(65), 'has space in it 123456', "quote'quote1234567890", '../../etc/passwd-0000']) expect(IDEMPOTENCY_KEY_PATTERN.test(bad)).toBe(false);
  });
});

describe('raceDeadline', () => {
  it('returns the value when the work is first, a timeout when the deadline is first, and swallows a late failure', async () => {
    expect(await raceDeadline(Promise.resolve(7), 50)).toEqual({ timedOut: false, value: 7 });
    expect(await raceDeadline(new Promise((r) => setTimeout(() => r(1), 80)), 10)).toEqual({ timedOut: true });
    const unhandled = vi.fn();
    process.on('unhandledRejection', unhandled);
    const late = new Promise((_, rej) => setTimeout(() => rej(new Error('late')), 30));
    expect(await raceDeadline(late, 5)).toEqual({ timedOut: true });
    await new Promise((r) => setTimeout(r, 60));
    process.off('unhandledRejection', unhandled);
    expect(unhandled).not.toHaveBeenCalled();
    await expect(raceDeadline(Promise.reject(new Error('boom')), 50)).rejects.toThrow('boom'); // a failure BEFORE the deadline is still a failure
  });
  it('a deadline already past is an immediate timeout', async () => {
    expect(await raceDeadline(new Promise((r) => setTimeout(() => r(1), 30)), -5)).toEqual({ timedOut: true });
  });
});

describe('NC-T1 / NC-T2: one key, one issued report', () => {
  it('the same key twice: one stored report, the second answer is the first report, flagged as a replay and computing nothing', async () => {
    const { call, rows, load } = setup(3);
    const a = await call({ key: KEY });
    const b = await call({ key: KEY });
    expect(a.status).toBe('ready');
    expect(b.status).toBe('ready');
    expect(rows()).toHaveLength(1);
    if (a.status === 'ready' && b.status === 'ready') {
      expect(b.report.id).toBe(a.report.id);
      expect(a.replayed).toBeUndefined();
      expect(b.replayed).toBe(true);
      expect(b.cache).toEqual({ hits: 0, computed: 0, stored: 0 });
    }
    expect(load).toHaveBeenCalledTimes(1); // the replay did not even load the data
  });

  it('six identical requests AT ONCE: exactly one report row exists and all six answers name it', async () => {
    const { call, rows } = setup(3);
    const out = await Promise.all(Array.from({ length: 6 }, () => call({ key: KEY })));
    expect(out.every((r) => r.status === 'ready')).toBe(true);
    expect(rows()).toHaveLength(1);
    const ids = new Set(out.map((r) => (r.status === 'ready' ? r.report.id : '')));
    expect(ids.size).toBe(1);
    expect(out.filter((r) => r.status === 'ready' && r.replayed === true).length).toBeGreaterThanOrEqual(1);
  });

  it('CONTROL: without a key two requests issue two reports (so it is the key that prevents the duplicate); two different keys issue two versions', async () => {
    const plain = setup(2);
    await plain.call();
    await plain.call();
    expect(plain.rows()).toHaveLength(2);
    expect(plain.rows().every((r) => r.idempotency_key === undefined)).toBe(true);
    const keyed = setup(2);
    await keyed.call({ key: KEY });
    await keyed.call({ key: 'another-key-0000000000000000' });
    expect(keyed.rows().map((r) => r.version_number)).toEqual([1, 2]);
  });

  it('the key and the request fingerprint are stored with the report (not in the report body)', async () => {
    const { call, rows } = setup(2);
    await call({ key: KEY, period: 'all_history' });
    expect(rows()[0].idempotency_key).toBe(KEY);
    expect(rows()[0].request_fingerprint).toBe(requestFingerprint('all_history', null));
    expect(JSON.stringify(rows()[0].report_json)).not.toContain(KEY);
  });

  it('the same key with a DIFFERENT period or a different fund choice is refused and issues nothing', async () => {
    const { call, rows } = setup(3);
    expect((await call({ key: KEY, period: 'since_first_held' })).status).toBe('ready');
    const other = await call({ key: KEY, period: 'all_history' });
    expect(other).toMatchObject({ status: 'idempotency_conflict' });
    const choice = await call({ key: KEY, funds: [idOf(0)] });
    expect(choice).toMatchObject({ status: 'idempotency_conflict' });
    expect(rows()).toHaveLength(1);
  });

  it('the fingerprint ignores the ORDER of the chosen funds and distinguishes none from some', () => {
    expect(requestFingerprint('since_first_held', ['b', 'a'])).toBe(requestFingerprint('since_first_held', ['a', 'b']));
    expect(requestFingerprint('since_first_held', null)).not.toBe(requestFingerprint('since_first_held', ['a']));
    expect(requestFingerprint('since_first_held', null)).not.toBe(requestFingerprint('all_history', null));
  });

  it('a free user with a key is refused before the key is looked at (no report, no oracle for another person\'s keys)', async () => {
    const { call, rows } = setup(2, { isPremium: async () => false });
    expect(await call({ key: KEY })).toMatchObject({ status: 'forbidden' });
    expect(rows()).toHaveLength(0);
  });

  it('another person\'s key is not found (the lookup is scoped to the caller)', async () => {
    const { call, rows, db } = setup(2);
    db.tables.nav2_fund_analytics_reports.push({ id: 'theirs', user_id: 'someone-else', version_number: 1, idempotency_key: KEY, request_fingerprint: requestFingerprint('since_first_held', null), as_of_date: AS_OF, scheme_count: 1, created_at: 'x', report_json: {} });
    const r = await call({ key: KEY });
    expect(r.status).toBe('ready');
    if (r.status === 'ready') expect(r.report.id).not.toBe('theirs');
    expect(rows().filter((x) => x.user_id === USER)).toHaveLength(1);
  });
});

describe('NC-T3 / NC-T4 / NC-T5: one clock, nothing partial, resumable and monotonic', () => {
  it('time already spent before the service starts shrinks what the engine may start', async () => {
    // 12 cold funds. A call that will NOT issue the report may use the engine until the deadline minus the small cache write; the less is left, the fewer start.
    const room = (elapsed: number) => Math.floor((REQUEST_DEADLINE_MS - CACHE_WRITE_RESERVE_MS - elapsed) / ENGINE_MS_PER_UNCACHED_FUND);
    const elapsed = GENERATION_BUDGET_MS - 4 * ENGINE_MS_PER_UNCACHED_FUND - 1;
    const { call, rows } = setup(12, { nowMs: () => elapsed });
    const r = await call({ requestStartedMs: 0 });
    expect(r).toMatchObject({ status: 'in_steps', ready: room(elapsed), total: 12 });
    expect(rows()).toHaveLength(0);
    // the same request with an earlier start (more time already gone) may start fewer
    const later = setup(12, { nowMs: () => elapsed });
    const gone = 2 * ENGINE_MS_PER_UNCACHED_FUND;
    expect(await later.call({ requestStartedMs: -gone })).toMatchObject({ status: 'in_steps', ready: room(elapsed + gone), total: 12 });
    expect(room(elapsed + gone)).toBeLessThan(room(elapsed));
  });

  it('PROGRESS GUARANTEE: when the reads before the engine used nearly the whole budget, a call still prepares at least one fund (it never livelocks at 0 ready)', async () => {
    const elapsed = GENERATION_BUDGET_MS + 500; // already past the issue budget
    const { call, db } = setup(5, { nowMs: () => elapsed });
    const r = await call({ requestStartedMs: 0 });
    expect(r.status).toBe('in_steps');
    if (r.status === 'in_steps') expect(r.ready).toBeGreaterThanOrEqual(1);
    expect(db.tables.nav2_result_cache.length).toBeGreaterThanOrEqual(1);
    // and with truly no room left (past the deadline minus the write) nothing starts
    const none = setup(5, { nowMs: () => REQUEST_DEADLINE_MS });
    expect(await none.call({ requestStartedMs: 0 })).toMatchObject({ status: 'in_steps', ready: 0, total: 5 });
  });

  it('with the whole deadline gone nothing is started and nothing is stored, but the answer is still the typed in-steps state', async () => {
    const { call, rows, db } = setup(5, { nowMs: () => REQUEST_DEADLINE_MS });
    const r = await call({ requestStartedMs: 0 });
    expect(r).toMatchObject({ status: 'in_steps', ready: 0, total: 5 });
    expect(rows()).toHaveLength(0);
    expect(db.tables.nav2_result_cache).toHaveLength(0);
  });

  it('NC-T4: the engine ends too late to persist: nothing is issued, the finished bundles are cached, the next call only persists and recomputes nothing', async () => {
    // all 3 funds are affordable at the start, but the clock jumps past the deadline minus the persist floor after the engine
    const clock = vi.fn();
    clock.mockReturnValueOnce(0).mockReturnValueOnce(0).mockReturnValue(REQUEST_DEADLINE_MS - MIN_PERSIST_MS + 1);
    const { call, rows, db } = setup(3, { nowMs: clock });
    const first = await call({ key: KEY });
    clock.mockReset();
    clock.mockReturnValue(0); // the next request starts afresh
    expect(first).toMatchObject({ status: 'in_steps', ready: 3, total: 3, retryAfterSeconds: 2 });
    expect(rows()).toHaveLength(0);
    expect(db.tables.nav2_result_cache).toHaveLength(3); // saved FIRST: the work is not lost
    const cachedBefore = db.tables.nav2_result_cache.length;
    const second = await call({ key: KEY, requestStartedMs: 0 });
    expect(second.status).toBe('ready');
    if (second.status === 'ready') expect(second.cache).toMatchObject({ hits: 3, computed: 0 });
    expect(rows()).toHaveLength(1);
    expect(db.tables.nav2_result_cache).toHaveLength(cachedBefore);
  });

  it('NC-T5: 12 cold funds with room for 4 per call: ready goes 4, 8, 12 (never down), then ONE report is issued; asking again with the key replays it', async () => {
    const { call, rows } = setup(12, { nowMs: () => GENERATION_BUDGET_MS - 4 * ENGINE_MS_PER_UNCACHED_FUND - 1 });
    const progress: number[] = [];
    let last = await call({ key: KEY, requestStartedMs: 0 });
    for (let i = 0; i < 6 && last.status === 'in_steps'; i++) {
      progress.push(last.ready);
      last = await call({ key: KEY, requestStartedMs: 0 });
    }
    expect(progress).toEqual([7, 12]); // 7 funds start in the first call (the extended room of a call that cannot issue), the second finishes the other 5, the third issues
    expect(progress.every((v, i) => i === 0 || v > progress[i - 1])).toBe(true);
    expect(last.status).toBe('ready');
    expect(rows()).toHaveLength(1);
    const again = await call({ key: KEY, requestStartedMs: 0 });
    expect(again).toMatchObject({ status: 'ready', replayed: true });
    expect(rows()).toHaveLength(1);
  });
});

describe('NC-T6 / NC-T7: no partial issue, and a database without migration 0281', () => {
  it('NC-T6: if the NAV range of a fund cannot be pinned the inserted report is removed again and the request fails (nothing partial stays)', async () => {
    const { call, rows, db } = setup(2, {}, { failDependencies: true });
    await expect(call({ key: KEY })).rejects.toThrow(/price history could not be protected/);
    expect(rows()).toHaveLength(0);
    expect(db.writes.some((w) => w.table === 'nav2_fund_analytics_reports' && w.kind === 'delete')).toBe(true);
    // and the same key can be tried again afterwards (the failed attempt left no key behind)
    const retry = setup(2);
    expect((await retry.call({ key: KEY })).status).toBe('ready');
  });

  it('NC-T7: without migration 0281 (no key columns) the report is still issued once, without replay protection', async () => {
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => undefined);
    const { call, rows } = setup(2, {}, { idempotencyColumns: false });
    const r = await call({ key: KEY });
    expect(r.status).toBe('ready');
    expect(rows()).toHaveLength(1);
    expect(rows()[0].idempotency_key).toBeUndefined();
    expect(warn).toHaveBeenCalled();
    warn.mockRestore();
  });
});
